// Verifies Wagent's Standard Webhooks signature when WAGENT_WEBHOOK_SECRET is available,
// then keeps only message.received events. Every other event type (draft.created,
// approval.requested, session events...) is dropped here.
const crypto = require('crypto');
const item = $input.first();
const headers = item.json.headers || {};

// The raw body is needed for the signature. The webhook node keeps it as binary "data".
let raw;
if (item.binary && item.binary.data) {
  raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
} else {
  raw = JSON.stringify(item.json.body || {});
}

// n8n Cloud and instances with N8N_BLOCK_ENV_ACCESS_IN_NODE=true cannot read env vars.
// Then the signature is not checked, and "Confirm message through the API" is the safeguard.
let secret = '';
try { secret = $env.WAGENT_WEBHOOK_SECRET || ''; } catch (e) { secret = ''; }

let signature = 'not_checked';
if (secret) {
  const id = headers['webhook-id'];
  const ts = Number(headers['webhook-timestamp']);
  if (!id || !Number.isFinite(ts) || Math.abs(Date.now() / 1000 - ts) > 300) return [];
  const key = Buffer.from(secret.replace(/^whsec_/, ''), 'base64');
  const want = crypto.createHmac('sha256', key).update(`${id}.${ts}.${raw}`).digest();
  const ok = String(headers['webhook-signature'] || '').split(' ').some((part) => {
    const [v, sig] = part.split(',');
    const got = Buffer.from(sig || '', 'base64');
    return v === 'v1' && got.length === want.length && crypto.timingSafeEqual(got, want);
  });
  if (!ok) return [];
  signature = 'valid';
}

let event;
try { event = JSON.parse(raw); } catch (e) { return []; }
if (!event || event.type !== 'message.received') return [];

const d = event.data || {};
const first = ((d.wagent_data || {}).items || [])[0];
if (!first || !first.source || !d.chat_id || !d.message_id) return [];

return [{
  json: {
    event_id: event.id,
    env: event.env,
    chat_id: d.chat_id,
    message_id: d.message_id,
    author: first.source.author,
    message_type: first.meta ? first.meta.type : null,
    signature,
  },
}];

// Confirms the webhook's message through the API (so a forged event cannot trigger a draft),
// skips chats someone already answered, and builds the transcript for the AI.
const s = $('Settings').first().json;
const items = ($input.first().json.wagent_data || {}).items || [];
const messages = items.filter((m) => m && m.source && m.source.kind === 'whatsapp_message');

const target = messages.find((m) => m.source.messageId === s.message_id);
if (!target) return [];                          // not readable through the API: never draft for it
if (!String(target.text || '').trim()) return []; // voice note, sticker or photo without a caption

const last = messages[messages.length - 1];
if (last && last.source.author === 'owner') return []; // someone already replied in this chat

const transcript = messages
  .map((m) => {
    const who = m.source.author === 'owner' ? 'Business' : (m.meta && m.meta.sender_name) || 'Customer';
    const text = m.text || `(${m.meta ? m.meta.type : 'message'} without text)`;
    return `[${m.source.sentAt}] ${who}: ${text}`;
  })
  .join('\n');

return [{
  json: {
    event_id: s.event_id,
    chat_id: s.chat_id,
    message_id: s.message_id,
    wagent_base_url: s.wagent_base_url,
    business_context: s.business_context,
    latest_message: target.text,
    transcript,
  },
}];

